Two agents keep handing a ticket back and forth. A hop counter is added. What does this print?

```python
class P(TypedDict):
    hops: int
    log: Annotated[list, operator.add]

def mk(name, other):
    def f(s) -> Command:
        if s["hops"] >= 3:
            return Command(goto=END, update={"log": [f"{name}:stop"]})
        return Command(goto=other, update={"hops": s["hops"] + 1, "log": [name]})
    return f

b = StateGraph(P)
b.add_node("billing", mk("billing", "tech"), destinations=("tech", END))
b.add_node("tech", mk("tech", "billing"), destinations=("billing", END))
b.add_edge(START, "billing")
print(b.compile().invoke({"hops": 0, "log": []}, {"recursion_limit": 10}))
```

A handoff from `alice` (a compiled subgraph node) adds a `task_description` for Bob. What does this print?

```python
class Child(TypedDict):
    log: Annotated[list, operator.add]
    task_description: str

class Parent(TypedDict):
    log: Annotated[list, operator.add]

def handoff(s):
    return Command(goto="bob", graph=Command.PARENT,
                   update={"log": ["alice"], "task_description": "refund #42"})

alice = StateGraph(Child).add_node(handoff).add_edge(START, "handoff").compile()
def bob(s): return {"log": [f"bob saw keys {sorted(s)}"]}

p = (StateGraph(Parent).add_node("alice", alice).add_node(bob)
     .add_edge(START, "alice").add_edge("bob", END))
print(p.compile().invoke({"log": []}))
```
